import * as persistedSessionStorage from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { EnrichedError } from './errorHandling/EnrichedError';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
const mockedSendErrorReport = jest.mocked(sendErrorReport);
const { STORAGE_PREFIX } = persistedSessionStorage;

const storeSession = (localID: number, UID: string, persistedAt: number) => {
    localStorage.setItem("'`${STORAGE_PREFIX}${localID}`, JSON.stringify({ UserID: `${localID}`, UID, persistedAt }));
};

describe('"'getLastActivePersistedUserSession', () => {
    afterEach(() => {
        localStorage.clear();
        jest.restoreAllMocks();
        jest.clearAllMocks();
    });

    it('returns null when there are no persisted sessions', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
    });

    it('returns the full session with the most recent persistedAt across accounts', () => {
        storeSession(123, 'first', 123);
        storeSession(456, 'latest', 567);
        storeSession(789, 'older', 345);
        localStorage.setItem('otherKey', JSON.stringify({ UID: 'unrelated', persistedAt: 999 }));

        expect(getLastActivePersistedUserSession()).toMatchObject({
            localID: 456,
            UserID: '456',
            UID: 'latest',
            persistedAt: 567,
        });
    });

    it('skips sessions without a UID and malformed entries', () => {
        storeSession(123, 'valid', 123);
        storeSession(456, '', 567);
        localStorage.setItem("'`${STORAGE_PREFIX}789`, '"'invalid JSON');
        localStorage.setItem("'`${STORAGE_PREFIX}invalid`, JSON.stringify({ UID: '"'invalid', persistedAt: 999 }));

        expect(getLastActivePersistedUserSession()).toMatchObject({ localID: 123, UID: 'valid' });
    });

    it('reports retrieval failures and returns null', () => {
        const error = new SyntaxError('Invalid persisted session');
        jest.spyOn(persistedSessionStorage, 'getPersistedSessions').mockImplementationOnce(() => {
            throw error;
        });

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.any(EnrichedError));
    });

    it('reports unavailable storage and returns null', () => {
        jest.spyOn(persistedSessionStorage, 'getPersistedSessions').mockImplementationOnce(() => {
            throw new DOMException('Storage unavailable', 'SecurityError');
        });

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.any(EnrichedError));
    });
});
EOF
