import { renderHook } from '@testing-library/react-hooks';

import { useActivePing } from './useActivePing';

const mockedApi = jest.fn();

jest.mock('@proton/components/hooks', () => ({
    useApi: () => jest.fn().mockImplementation(mockedApi.mockResolvedValue('')),
}));

describe('useActivePing', () => {
    beforeAll(() => {
        jest.useFakeTimers();
    });

    afterEach(() => {
        jest.clearAllMocks();
        jest.clearAllTimers();
    });

    afterAll(() => {
        jest.useRealTimers();
    });

    it('calls the api immediately and periodically', () => {
        renderHook(() => useActivePing(1000));
        expect(mockedApi).toHaveBeenCalledTimes(1);

        jest.advanceTimersByTime(1000);
        expect(mockedApi).toHaveBeenCalledTimes(2);
    });

    it('does not call api before the interval has passed', () => {
        const { rerender } = renderHook(() => useActivePing(10000));
        jest.advanceTimersByTime(5000);
        rerender();
        expect(mockedApi).toHaveBeenCalledTimes(1);
    });

    it('calls api only when the document is visible', () => {
        Object.defineProperty(document, 'visibilityState', { value: 'hidden', configurable: true });
        renderHook(() => useActivePing());
        expect(mockedApi).not.toHaveBeenCalled();

        Object.defineProperty(document, 'visibilityState', { value: 'visible', configurable: true });
        document.dispatchEvent(new Event('visibilitychange'));
        expect(mockedApi).toHaveBeenCalledTimes(1);
    });
});
